package com.bank.flink.wa;

import java.util.ArrayList;
import java.util.List;

// Stands in for the window table-valued functions. For an event, returns the
// list of [window_start, window_end] pairs it belongs to.
class WindowTvf {

    // TUMBLE: exactly one non-overlapping window.
    static List<long[]> tumble(long ts, long sizeMs) {
        long start = ts - (ts % sizeMs);
        List<long[]> out = new ArrayList<>();
        out.add(new long[]{ start, start + sizeMs });
        return out;
    }

    // HOP: possibly several overlapping windows (size / slide of them).
    static List<long[]> hop(long ts, long slideMs, long sizeMs) {
        List<long[]> out = new ArrayList<>();
        // last window start <= ts, stepping back by slide while window still covers ts
        long firstStart = ts - (ts % slideMs);
        for (long start = firstStart; start + sizeMs > ts; start -= slideMs) {
            if (start <= ts && ts < start + sizeMs) {
                out.add(new long[]{ start, start + sizeMs });
            }
        }
        return out;
    }

    // CUMULATE: windows share a start, grow by step up to max; event belongs to
    // every cumulative window whose end is > ts within the max.
    static List<long[]> cumulate(long ts, long stepMs, long maxMs) {
        long cycleStart = ts - (ts % maxMs);
        List<long[]> out = new ArrayList<>();
        for (long end = cycleStart + stepMs; end <= cycleStart + maxMs; end += stepMs) {
            if (ts < end) {
                out.add(new long[]{ cycleStart, end });
            }
        }
        return out;
    }
}
