package com.bank.flink.wa;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.logging.Logger;

// Groups by (window_start, window_end, account_id) and sums amounts, as the
// GROUP BY of a window TVF query would. Append-only: emit once per window.
class WindowedAggregator {
    private static final Logger log = Logger.getLogger(WindowedAggregator.class.getName());

    // key = "start|end|account" -> [count, total]
    private final Map<String, BigDecimal[]> groups = new TreeMap<>();

    void assignAndAggregate(Txn txn, List<long[]> windows) {
        for (long[] w : windows) {
            String key = w[0] + "|" + w[1] + "|" + txn.getAccountId();
            BigDecimal[] acc = groups.computeIfAbsent(key, k -> new BigDecimal[]{ BigDecimal.ZERO, BigDecimal.ZERO });
            acc[0] = acc[0].add(BigDecimal.ONE);              // count
            acc[1] = acc[1].add(txn.getAmount());             // total
        }
    }

    void emitAll(String label) {
        log.info(() -> "=== " + label + " results (window_start|window_end|account -> count,total) ===");
        groups.forEach((key, acc) ->
                log.info(() -> label + " " + key + " -> count=" + acc[0] + " total=" + acc[1]));
        groups.clear();
    }
}
