package com.bank.flink.wa;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: same transactions through TUMBLE, HOP, and CUMULATE.
public class WindowedSqlDemo {
    private static final Logger log = Logger.getLogger(WindowedSqlDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new WaLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Txn[] stream = {
            new Txn("SAV2001", new BigDecimal("100"), 10_000),  // 00:10
            new Txn("SAV2001", new BigDecimal("200"), 50_000),  // 00:50
            new Txn("SAV2001", new BigDecimal("300"), 70_000),  // 01:10
            new Txn("CUR3001", new BigDecimal("500"), 40_000)   // 00:40
        };

        // TUMBLE 1 minute (60000 ms)
        WindowedAggregator tumble = new WindowedAggregator();
        for (Txn t : stream) tumble.assignAndAggregate(t, WindowTvf.tumble(t.getEventTimeMillis(), 60_000));
        tumble.emitAll("TUMBLE");

        // HOP size 1 min, slide 30 s
        WindowedAggregator hop = new WindowedAggregator();
        for (Txn t : stream) hop.assignAndAggregate(t, WindowTvf.hop(t.getEventTimeMillis(), 30_000, 60_000));
        hop.emitAll("HOP");

        // CUMULATE step 1 min, max 5 min
        WindowedAggregator cumulate = new WindowedAggregator();
        for (Txn t : stream) cumulate.assignAndAggregate(t, WindowTvf.cumulate(t.getEventTimeMillis(), 60_000, 300_000));
        cumulate.emitAll("CUMULATE");
    }
}

